const framedConsumer = String.raw`import os,sys,re,json,io,hashlib
class FrameError(Exception):pass
def fail(code):raise FrameError(code)
def exact_read(count):
    parts=[]
    while count:
        chunk=os.read(0,min(65536,count))
        if not chunk:fail('TRUNCATED')
        parts.append(chunk);count-=len(chunk)
    return b''.join(parts)
try:
    if len(sys.argv)!=4:fail('ARGUMENTS')
    length_text,digest,label=sys.argv[1:]
    if not re.fullmatch('[0-9a-f]{16}',length_text) or not re.fullmatch('[0-9a-f]{64}',digest):fail('ARGUMENTS')
    required=int(length_text,16)
    if required<=0 or required>9007199254740991 or required>sys.maxsize:fail('LENGTH')
    if label not in ['frozen-runtime-fixture','release-lineage-field-regression','shared-capture-lineage']:fail('LABEL')
    header=exact_read(88)
    if header[:8]!=b'SLFRAME1':fail('VERSION')
    if not re.fullmatch(b'[0-9a-f]{16}',header[8:24]) or not re.fullmatch(b'[0-9a-f]{64}',header[24:88]):fail('HEADER')
    if header[8:24].decode()!=length_text:fail('LENGTH')
    if header[24:88].decode()!=digest:fail('SHA256')
    body=exact_read(required)
    if hashlib.sha256(body).hexdigest()!=digest:fail('SHA256')
    payload=json.loads(body.decode('utf-8',errors='strict'))
    if not isinstance(payload,dict) or not isinstance(payload.get('_guard_model'),str):fail('PAYLOAD')
    source=payload.pop('_guard_model')
except (FrameError,OSError,ValueError,UnicodeError,MemoryError,OverflowError) as error:
    code=str(error) if isinstance(error,FrameError) else 'TRANSPORT'
    print('FRAME_'+code,file=sys.stderr);sys.exit(2)
sys.argv=['-c']
sys.stdin=io.StringIO(json.dumps(payload))
exec(compile(source,label,'exec'))
`;
function encodeFramedInput(serialized, label = 'frozen-runtime-fixture') {
  assert.equal(typeof serialized, 'string');
  const payload = Buffer.from(serialized, 'utf8');
  assert.ok(Number.isSafeInteger(payload.length) && payload.length > 0);
  const length = payload.length.toString(16).padStart(16, '0');
  const digest = sha(payload);
  const header = Buffer.from(`SLFRAME1${length}${digest}`, 'ascii');
  assert.equal(header.length, 88);
  const frame = Buffer.concat([header, payload]);
  assert.equal(frame.length, 88 + payload.length);
  return { frame, payload, length, digest, args: ['-c', framedConsumer, length, digest, label] };
}
function framedPython(label, options) {
  const encoded = encodeFramedInput(options.input, label);
  return spawnSync('python3', encoded.args, { ...options, input: encoded.frame });
}

