 assert.notEqual(stale,guard);
 const assess=(source,name)=>{const result=framedPython("frozen-runtime-fixture",{cwd:repositoryRoot,encoding:'utf8',timeout:60000,input:JSON.stringify({case:name,delta:runtimeRepairExpectedDelta,_guard_model:runtimeGuardModel,g5Delta:g5HostedExpectedDelta,priorG5Delta:priorG5HostedExpectedDelta,implementationDelta:runtimeExpectedDelta,guard:source})});assert.equal(result.status,0,result.stderr);return JSON.parse(result.stdout);};
