const captureTreeNegatives=[
 ['wrong_capture_tree','CAPTURE_PARENT_TREE_MISMATCH',1],
 ['missing_capture_tree','CAPTURE_PARENT_TREE_FORMAT',1],
 ['malformed_capture_tree','CAPTURE_PARENT_TREE_FORMAT',1],
 ['capture_tree_from_prior_candidate','CAPTURE_PARENT_TREE_MISMATCH',1],
 ['capture_tree_conflicts_with_subject','CAPTURE_PARENT_OBJECT_IDENTITY',0],
];
for(const name of ['valid','wrong_parent','wrong_capture_tree','extra_path','missing_path','duplicate_path','wrong_mode','wrong_status','publication_wrong_tree','publication_wrong_delta'])test('G5 shared capture lineage: '+name,()=>{
 const cases=name==='wrong_capture_tree'?captureTreeNegatives:[[name,null,null]];
 for(const [variant,error,observedCalls] of cases){
  const result=framedPython("shared-capture-lineage",{cwd:repositoryRoot,encoding:'utf8',timeout:60000,input:JSON.stringify({case:variant,capture_generation:true,delta:runtimeRepairExpectedDelta,_guard_model:runtimeGuardModel,g5Delta:sharedCaptureExpectedDelta,priorG5Delta:priorG5HostedExpectedDelta,implementationDelta:runtimeExpectedDelta,guard:ciPython[0]})});
  assert.equal(result.status,0,result.stderr);const value=JSON.parse(result.stdout);assert.equal(value.accepted,name==='valid',JSON.stringify(value));
  if(error){assert.equal(value.error,error);assert.deepEqual(value.tree_trace,{raw_commit_calls:1,observed_tree_calls:observedCalls,mutation_hits:1});}
  if(name==='valid')assert.deepEqual(value.tree_trace,{raw_commit_calls:2,observed_tree_calls:1,mutation_hits:0});
  if(error||name==='valid')console.log('CAPTURE_TREE_TRACE '+JSON.stringify({case:variant,...value}));
 }
});

function framedRuntimePayload(overrides = {}) {
  return {case:'valid',delta:runtimeRepairExpectedDelta,_guard_model:runtimeGuardModel,g5Delta:g5HostedExpectedDelta,priorG5Delta:priorG5HostedExpectedDelta,implementationDelta:runtimeExpectedDelta,guard:previousGenerationPython[0],...overrides};
}
function framedSemantic(overrides, accepted, error, mode) {
  const result=framedPython('frozen-runtime-fixture',{cwd:repositoryRoot,env:process.env,encoding:'utf8',timeout:60000,input:JSON.stringify(framedRuntimePayload(overrides))});
  assert.equal(result.status,0,result.stderr);assert.equal(result.signal,null);
  const value=JSON.parse(result.stdout);assert.equal(value.accepted,accepted,JSON.stringify(value));
  if(error)assert.equal(value.error,error);if(mode)assert.equal(value.mode,mode);return value;
}
const framedProofNames = ['valid_clean_local','valid_simulated_hosted','missing_local_binding','functional_drift','duplicate_path','prior_stalled_cases','delayed_eof','writer_open','truncated_frame','oversized_declared_length','undersized_declared_length','wrong_sha','malformed_version_header','semantic_negative_controls','native_timeout'];
function framedMutation(input, mutate) {
  const encoded=encodeFramedInput(input);const frame=mutate(Buffer.from(encoded.frame));
  const result=spawnSync('python3',encoded.args,{cwd:repositoryRoot,env:process.env,encoding:'utf8',timeout:60000,input:frame});
  assert.equal(result.status,2,result.stderr);assert.match(result.stderr,/FRAME_/);assert.equal(result.stdout,'');return result;
}
async function openWriterProof(holdMs = 0) {
  // Real frozen runtime model and semantic guard; a test-only post-verdict hold
  // keeps the process and its peer alive so writer-open duration is observable.
  const payload=framedRuntimePayload();
  if(holdMs)payload._guard_model += '\nimport time\ntime.sleep(2)\n';
  const encoded=encodeFramedInput(JSON.stringify(payload));
  const child=spawn('python3',encoded.args,{cwd:repositoryRoot,env:{...process.env,PYTHONUNBUFFERED:'1'},stdio:['pipe','pipe','pipe'],timeout:60000});
  let stdout='',stderr='',ended=false;const start=performance.now();let progressAt=null,closeAt=null;
  child.stderr.on('data',x=>stderr+=x);let failure;
  const progress=new Promise((resolve,reject)=>{child.stdout.on('data',x=>{stdout+=x;try{const value=JSON.parse(stdout);if(value.accepted===true&&progressAt===null){progressAt=performance.now();assert.equal(ended,false);assert.equal(child.stdin.writableEnded,false);assert.equal(child.stdin.destroyed,false);resolve(value);}}catch(e){if(e instanceof assert.AssertionError)reject(e);}});child.once('error',reject);child.once('exit',(code,signal)=>{if(progressAt===null)reject(Error(JSON.stringify({code,signal,stderr,stdout})));});});
  const exit=new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',(code,signal)=>resolve({code,signal}));});
  child.stdin.on('error',error=>{failure=error;});
  child.stdin.write(encoded.frame);
  await progress;
  if(holdMs){await new Promise(resolve=>setTimeout(resolve,holdMs));assert.equal(child.stdin.destroyed,false);assert.equal(child.stdin.writableEnded,false);}
  ended=true;closeAt=performance.now();child.stdin.end();
  const result=await exit;assert.equal(result.code,0,stderr);assert.equal(result.signal,null);assert.ok(!failure,String(failure));assert.ok(progressAt<closeAt);if(holdMs)assert.ok(closeAt-progressAt>=holdMs-5);
  console.log('FRAMED_EOF_INDEPENDENCE '+JSON.stringify({payloadBytes:encoded.payload.length,payloadSHA256:encoded.digest,modelVerdictMs:progressAt-start,writerEndMs:closeAt-start,writerOpenAtVerdict:true,holdMs,timeout:60000}));
}
async function incompleteOpenTimeout() {
  const encoded=encodeFramedInput(JSON.stringify(framedRuntimePayload()));
  const child=spawn('python3',encoded.args,{cwd:repositoryRoot,env:process.env,stdio:['pipe','pipe','pipe'],timeout:60000});
  let stdout='',stderr='';child.stdout.on('data',x=>stdout+=x);child.stderr.on('data',x=>stderr+=x);child.stdin.on('error',()=>{});
  const start=performance.now();const exit=new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',(code,signal)=>resolve({code,signal}));});
  child.stdin.write(encoded.frame.subarray(0,encoded.frame.length-1));
  const result=await exit;assert.equal(result.code,null);assert.equal(result.signal,'SIGTERM');assert.equal(stdout,'');assert.ok(performance.now()-start>=59000);console.log('FRAMED_TIMEOUT '+JSON.stringify({...result,durationMs:performance.now()-start,timeout:60000,modelExecuted:false,stderr}));
}
function synchronousCompleteFrameTimeoutProof() {
  const payload=framedRuntimePayload({_guard_model:"import sys,threading\nprint('NATIVE_TIMEOUT_MODEL_BEGIN',file=sys.stderr,flush=True)\nthreading.Event().wait()\n"});
  const serialized=JSON.stringify(payload);const encoded=encodeFramedInput(serialized);
  assert.equal(encoded.frame.length,88+encoded.payload.length);
  const started=performance.now();
  const result=framedPython('frozen-runtime-fixture',{cwd:repositoryRoot,env:process.env,encoding:'utf8',timeout:60000,input:serialized});
  const durationMs=performance.now()-started;
  assert.equal(result.status,null);assert.equal(result.signal,'SIGTERM');assert.equal(result.error?.code,'ETIMEDOUT');
  assert.equal(result.stdout,'');assert.match(result.stderr,/NATIVE_TIMEOUT_MODEL_BEGIN/);assert.ok(durationMs>=59000);
  console.log('FRAMED_NATIVE_TIMEOUT '+JSON.stringify({completeFrameBytes:encoded.frame.length,payloadSHA256:encoded.digest,modelExecutionReached:true,status:result.status,signal:result.signal,error:result.error.code,durationMs,timeout:60000}));
}
for(const name of framedProofNames)test('G5 framed transport: '+name,async()=>{
  if(name==='valid_clean_local')framedSemantic({admission_case:'local',synthetic_context:'clean_local'},true,null,'LOCAL_GOVERNED_SUBJECT');
  else if(name==='valid_simulated_hosted')framedSemantic({admission_case:'hosted',synthetic_context:'simulated_hosted'},true,null,'HOSTED_PUSH_EVENT');
  else if(name==='missing_local_binding'||name==='functional_drift')for(const synthetic_context of ['clean_local','simulated_hosted'])framedSemantic({admission_case:name,synthetic_context},false,name==='functional_drift'?'LOCAL_BYTES_CHANGED':'WRONG_IMPLEMENTATION_CHECKOUT');
  else if(name==='duplicate_path')framedSemantic({case:'duplicate_path'},false);
  else if(name==='prior_stalled_cases'){
    for(const caseName of ['stale_material','wrong_sha'])framedSemantic({case:caseName},false);
    framedSemantic({case:'extra_path',guard:previousGenerationPython[0]},false);
    framedSemantic({admission_case:'prior_hosted',synthetic_context:'simulated_hosted'},true,null,'HOSTED_PUSH_EVENT');
    framedSemantic({admission_case:'wrong_subject_hash',synthetic_context:'clean_local'},false,'LOCAL_SUBJECT_UNBOUND');
  } else if(name==='delayed_eof')await openWriterProof();
  else if(name==='writer_open')await openWriterProof(1000);
  else if(name==='truncated_frame'){
    for(const size of [1,87,-1])assert.match(framedMutation(JSON.stringify(framedRuntimePayload()),b=>size<0?b.subarray(0,b.length-1):b.subarray(0,size)).stderr,/FRAME_TRUNCATED/);
    const encoded=encodeFramedInput(JSON.stringify(framedRuntimePayload()));
    const child=spawn('python3',encoded.args,{cwd:repositoryRoot,env:process.env,stdio:['pipe','pipe','pipe'],timeout:60000});let out='',err='';child.stdout.on('data',x=>out+=x);child.stderr.on('data',x=>err+=x);child.stdin.on('error',()=>{});
    const done=new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',(code,signal)=>resolve({code,signal}));});child.stdin.end(encoded.frame.subarray(0,100));const result=await done;assert.equal(result.code,2);assert.equal(out,'');assert.match(err,/FRAME_TRUNCATED/);
    await incompleteOpenTimeout();
  } else if(name==='oversized_declared_length'||name==='undersized_declared_length'){
    framedMutation(JSON.stringify(framedRuntimePayload()),b=>{const n=BigInt('0x'+b.subarray(8,24).toString())+(name==='oversized_declared_length'?1n:-1n);b.write(n.toString(16).padStart(16,'0'),8,'ascii');return b;});
  } else if(name==='wrong_sha'){
    framedMutation(JSON.stringify(framedRuntimePayload()),b=>{b[24]=b[24]===48?49:48;return b;});
    framedMutation(JSON.stringify(framedRuntimePayload()),b=>{b[b.length-1]^=1;return b;});
  } else if(name==='malformed_version_header'){
    for(const [offset,value]of [[0,'X'],[7,'2'],[8,'-'],[8,'G'],[8,' '],[24,'G']])framedMutation(JSON.stringify(framedRuntimePayload()),b=>{b.write(value,offset,'ascii');return b;});
    framedMutation(JSON.stringify(framedRuntimePayload()),b=>{b.write('0000000000000000',8,'ascii');return b;});
  } else if(name==='semantic_negative_controls'){
    for(const [admission_case,error]of [['extra_path','LOCAL_SCOPE_INVALID'],['missing_path','LOCAL_SCOPE_INVALID'],['mixed_hosted_local','LOCAL_HOSTED_ROLE_CONFLICT'],['wrong_collector','LOCAL_COLLECTOR_UNBOUND']])framedSemantic({admission_case,synthetic_context:'simulated_hosted'},false,error);
  } else if(name==='native_timeout')synchronousCompleteFrameTimeoutProof();
  else assert.fail('Unknown framing proof family');
});
